const item = $input.first().json.body || $input.first().json;

const deviceCode = item.deviceCode || 'ANPR-GATE-01';
const deviceName = item.deviceName || 'North Main Gate ANPR Camera';
const deviceType = item.deviceType || 'ANPR_CAMERA'; // ANPR_CAMERA, BOOM_BARRIER, RFID_READER, QR_SCANNER, SMART_LOCK, TURNSTILE, CCTV_ANALYTICS, INTERCOM
const isOnline = item.isOnline ?? false;
const ipAddress = item.ipAddress || '192.168.10.45';
const location = item.location || 'North Main Gate Entry Lane';
const lastHeartbeatAt = item.lastHeartbeatAt || new Date(Date.now() - 35 * 60000).toISOString();
const offlineMinutes = item.offlineMinutes ?? 35;
const manualOverridesCount = item.manualOverridesCount ?? 0;
const sensorErrorFlags = item.sensorErrorFlags || ['OPTICAL_OCCLUSION_WARNING', 'HEARTBEAT_TIMEOUT'];
const firmwareVersion = item.firmwareVersion || 'v2.4.12';

const prompt = `You are the Lead IoT Infrastructure Engineer & Physical Security Sentinel for Mana Community Society.
Evaluate the following hardware telemetry and diagnostic health snapshot from a critical perimeter security device.

Hardware Telemetry Snapshot:
- Device Code: ${deviceCode} (${deviceName})
- Device Type: ${deviceType}
- Status: ${isOnline ? 'ONLINE' : 'OFFLINE'} (Offline for ${offlineMinutes} mins)
- IP / Location: ${ipAddress} at ${location}
- Last Ping Heartbeat: ${lastHeartbeatAt}
- Manual Physical Overrides: ${manualOverridesCount}
- Hardware Error Flags: ${JSON.stringify(sensorErrorFlags)}
- Installed Firmware: ${firmwareVersion}

Diagnostic Mandates:
1. Assess Perimeter Vulnerability Risk (CRITICAL_BREACH_WINDOW, ELEVATED_OPERATIONAL_RISK, MINOR_GLITCH, NOMINAL).
2. Root Cause Analysis (e.g. power PoE drop, physical camera lens tampering/spray paint, mechanical gear jam on boom barrier, switch port flapping).
3. Tamper / Sabotage Likelihood Assessment (HIGH, SUSPICIOUS, UNLIKELY_HARDWARE_FAILURE).
4. Guard Contingency Protocol: Immediate fallback procedure for gate guards while hardware is compromised (e.g. manual physical ledger, dual-guard verification).
5. Automated Facility Maintenance Work-Order: Generate urgency, repair instructions, and required spare parts.

Respond ONLY with a valid JSON object matching this exact schema:
{
  "vulnerabilityRisk": "CRITICAL_BREACH_WINDOW" | "ELEVATED_OPERATIONAL_RISK" | "MINOR_GLITCH" | "NOMINAL",
  "tamperLikelihood": "HIGH" | "SUSPICIOUS" | "UNLIKELY_HARDWARE_FAILURE",
  "rootCauseHypothesis": "Detailed technical explanation of device state",
  "immediateGuardProtocol": [
    "Guard step 1",
    "Guard step 2"
  ],
  "maintenanceTicket": {
    "priority": "EMERGENCY_P1" | "HIGH_P2" | "ROUTINE_P3",
    "assignedVendor": string,
    "targetResolutionHours": number,
    "repairProcedure": string
  },
  "commandCenterAlertBanner": "Single clear urgent banner message for security dashboard"
}`;

return [{
  json: {
    deviceCode,
    deviceName,
    deviceType,
    isOnline,
    prompt
  }
}];

const geminiResponse = $input.first().json;
const meta = $('Prepare Hardware Diagnostic Prompt').first().json;
let parsed = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (err) {
  const isDown = !meta.isOnline;
  parsed = {
    vulnerabilityRisk: isDown ? "ELEVATED_OPERATIONAL_RISK" : "NOMINAL",
    tamperLikelihood: "UNLIKELY_HARDWARE_FAILURE",
    rootCauseHypothesis: isDown ? "Network timeout or PoE switch port renegotiation delay." : "Device operating within standard operational parameters.",
    immediateGuardProtocol: isDown ? [
      "Deploy secondary manual guard with mobile ANPR backup app to gate.",
      "Log all vehicle license plates in manual gate register until telemetry recovers."
    ] : ["Maintain standard automated gate operation."],
    maintenanceTicket: {
      priority: isDown ? "HIGH_P2" : "ROUTINE_P3",
      assignedVendor: "Estate IoT & Automation Team",
      targetResolutionHours: isDown ? 2 : 24,
      repairProcedure: isDown ? "Check physical PoE injector and reboot local switch port." : "Routine quarterly diagnostic scan."
    },
    commandCenterAlertBanner: isDown ? `WARNING: ${meta.deviceName} is offline. Manual gate backup active.` : `${meta.deviceName} is healthy.`
  };
}

return [{
  json: {
    status: "success",
    evaluatedAt: new Date().toISOString(),
    deviceCode: meta.deviceCode,
    deviceName: meta.deviceName,
    diagnostics: parsed
  }
}];
